import{J as e,n as t,ot as n,q as r}from"./chunks/framework.DStH8c-G.js";var i=JSON.parse(`{"title":"Class: Entity","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Class: Entity"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/prismarine/classes/Entity"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/prismarine/classes/Entity"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/prismarine/src"}},"headers":[],"relativePath":"api/@jsprismarine/prismarine/classes/Entity.md","filePath":"api/@jsprismarine/prismarine/classes/Entity.md","lastUpdated":1794453737000}`),a={name:`api/@jsprismarine/prismarine/classes/Entity.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e('<p><a href="./../../../">API reference</a> / <a href="./../">@jsprismarine/prismarine</a> / Entity</p><h1 id="class-entity" tabindex="-1">Class: Entity <a class="header-anchor" href="#class-entity" aria-label="Permalink to “Class: Entity”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L114" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:114</a></p><p>The base class for all entities including <code>Player</code>.</p><h2 id="extended-by" tabindex="-1">Extended by <a class="header-anchor" href="#extended-by" aria-label="Permalink to “Extended by”">​</a></h2><ul><li><a href="./../namespaces/Entities/classes/Item.html"><code>Item</code></a></li></ul><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new Entity</strong>(<code>options</code>): <code>Entity</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L264" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:264</a></p><p>Entity constructor.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="options" tabindex="-1">options <a class="header-anchor" href="#options" aria-label="Permalink to “options”">​</a></h5><p>The entity options.</p><h6 id="attributes" tabindex="-1">attributes? <a class="header-anchor" href="#attributes" aria-label="Permalink to “attributes?”">​</a></h6><p><code>Attribute</code>[]</p><p>Initial attributes, or this entity&#39;s defaults when omitted.</p><h6 id="headyaw" tabindex="-1">headYaw? <a class="header-anchor" href="#headyaw" aria-label="Permalink to “headYaw?”">​</a></h6><p><code>number</code> = <code>0</code></p><p>The head yaw.</p><h6 id="pitch" tabindex="-1">pitch? <a class="header-anchor" href="#pitch" aria-label="Permalink to “pitch?”">​</a></h6><p><code>number</code> = <code>0</code></p><p>The pitch.</p><h6 id="position" tabindex="-1">position <a class="header-anchor" href="#position" aria-label="Permalink to “position”">​</a></h6><p><a href="./Position.html"><code>Position</code></a></p><p>Where the entity is, and in which world.</p><h6 id="runtimeid" tabindex="-1">runtimeId? <a class="header-anchor" href="#runtimeid" aria-label="Permalink to “runtimeId?”">​</a></h6><p><code>bigint</code></p><p>An id already drawn from Entity.runtimeIdCount, for a body whose entity was given its id elsewhere: a data-driven mob&#39;s runtime draws from the same counter, and its body takes that id so the mob has one id rather than two.</p><h6 id="yaw" tabindex="-1">yaw? <a class="header-anchor" href="#yaw" aria-label="Permalink to “yaw?”">​</a></h6><p><code>number</code> = <code>0</code></p><p>The yaw.</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>Entity</code></p><p>The entity instance.</p><h4 id="remarks" tabindex="-1">Remarks <a class="header-anchor" href="#remarks" aria-label="Permalink to “Remarks”">​</a></h4><p>The server is taken from the position&#39;s world rather than passed alongside it, so the two can never disagree about which server the entity belongs to.</p><h4 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to “Example”">​</a></h4><div class="language-typescript" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes jsprismarine jsprismarine" style="--shiki-light:#e5e7d7;--shiki-dark:#e5e7d7;--shiki-light-bg:#0b1713;--shiki-dark-bg:#0b1713;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">const</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;"> world </span><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">=</span><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;"> server.getWorldManager</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">()</span><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;">.getDefaultWorld</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">();</span></span>\n<span class="line"><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">const</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;"> entity </span><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">=</span><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;"> new</span><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;"> Entity</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">({ position: </span><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">new</span><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;"> Position</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">(</span><span style="--shiki-light:#FF6B3D;--shiki-dark:#FF6B3D;">0</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">, </span><span style="--shiki-light:#FF6B3D;--shiki-dark:#FF6B3D;">64</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">, </span><span style="--shiki-light:#FF6B3D;--shiki-dark:#FF6B3D;">0</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">, world) });</span></span></code></pre></div><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="attributes-1" tabindex="-1">attributes <a class="header-anchor" href="#attributes-1" aria-label="Permalink to “attributes”">​</a></h3><blockquote><p><code>readonly</code> <strong>attributes</strong>: <code>Attributes</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L168" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:168</a></p><p>Entity attributes.</p><p>What is in it is decided by Entity.getDefaultAttributes, which subclasses override - a player has a food bar, a cow does not.</p><hr><h3 id="constructor-1" tabindex="-1">constructor <a class="header-anchor" href="#constructor-1" aria-label="Permalink to “constructor”">​</a></h3><blockquote><p><strong>constructor</strong>: <em>typeof</em> <code>Entity</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L119" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:119</a></p><p>TypeScript types <code>this.constructor</code> as <code>Function</code>. Declaring it as the class itself lets <a href="#gettype">Entity.getType</a> read the static <code>MOB_ID</code> the subclass set. Emits nothing.</p><hr><h3 id="headyaw-1" tabindex="-1">headYaw <a class="header-anchor" href="#headyaw-1" aria-label="Permalink to “headYaw”">​</a></h3><blockquote><p><strong>headYaw</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L148" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:148</a></p><hr><h3 id="metadata" tabindex="-1">metadata <a class="header-anchor" href="#metadata" aria-label="Permalink to “metadata”">​</a></h3><blockquote><p><code>readonly</code> <strong>metadata</strong>: <code>Metadata</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L153" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:153</a></p><p>Entity metadata.</p><hr><h3 id="persistentnbt" tabindex="-1">persistentNbt <a class="header-anchor" href="#persistentnbt" aria-label="Permalink to “persistentNbt”">​</a></h3><blockquote><p><strong>persistentNbt</strong>: <a href="./../../nbt/classes/NBTTagCompound.html"><code>NBTTagCompound</code></a> | <code>null</code> = <code>null</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L178" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:178</a></p><p>Everything the world file said about this entity that the server does not model.</p><p>Vanilla actor NBT carries a <code>definitions</code> list naming the behavior pack component groups the entity was built from, along with its attributes, tags and variant. An actor written back without them spawns broken or despawns on sight, so the remainder is kept here and written out again by <code>EntitySerializer</code>. Null for an entity that was never read from disk.</p><hr><h3 id="pitch-1" tabindex="-1">pitch <a class="header-anchor" href="#pitch-1" aria-label="Permalink to “pitch”">​</a></h3><blockquote><p><strong>pitch</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L146" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:146</a></p><hr><h3 id="yaw-1" tabindex="-1">yaw <a class="header-anchor" href="#yaw-1" aria-label="Permalink to “yaw”">​</a></h3><blockquote><p><strong>yaw</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L147" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:147</a></p><h2 id="accessors" tabindex="-1">Accessors <a class="header-anchor" href="#accessors" aria-label="Permalink to “Accessors”">​</a></h2><h3 id="tostringtag" tabindex="-1">[toStringTag] <a class="header-anchor" href="#tostringtag" aria-label="Permalink to “[toStringTag]”">​</a></h3><h4 id="get-signature" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>[toStringTag]</strong>(): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L409" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:409</a></p><p>Get the entity type.</p><h5 id="example-1" tabindex="-1">Example <a class="header-anchor" href="#example-1" aria-label="Permalink to “Example”">​</a></h5><div class="language-typescript" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes jsprismarine jsprismarine" style="--shiki-light:#e5e7d7;--shiki-dark:#e5e7d7;--shiki-light-bg:#0b1713;--shiki-dark-bg:#0b1713;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">const</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;"> entityType </span><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">=</span><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;"> entity.getType</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">();</span></span>\n<span class="line"><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;">console.log</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">(</span><span style="--shiki-light:#A9D9C6;--shiki-dark:#A9D9C6;">`Entity type: ${</span><span style="--shiki-light:#A9D9C6;--shiki-dark:#A9D9C6;">entityType</span><span style="--shiki-light:#A9D9C6;--shiki-dark:#A9D9C6;">}`</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">);</span></span></code></pre></div><h5 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h5><p><code>string</code></p><p>The entity&#39;s namespace ID.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="addstatuseffect" tabindex="-1">addStatusEffect() <a class="header-anchor" href="#addstatuseffect" aria-label="Permalink to “addStatusEffect()”">​</a></h3><blockquote><p><strong>addStatusEffect</strong>(<code>input</code>, <code>notify?</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L747" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:747</a></p><p>Applies or refreshes a status effect.</p><p>A stronger Bedrock effect replaces the weaker one. An equal-strength effect only replaces the current value when it lasts longer or changes its visible state.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="input" tabindex="-1">input <a class="header-anchor" href="#input" aria-label="Permalink to “input”">​</a></h5><p><a href="./../#statuseffectinput"><code>StatusEffectInput</code></a></p><p>The effect and its duration, potency, and display flags.</p><h5 id="notify" tabindex="-1">notify? <a class="header-anchor" href="#notify" aria-label="Permalink to “notify?”">​</a></h5><p><code>boolean</code> = <code>true</code></p><p>Whether to send an effect packet for an accepted change.</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p>Whether the effect changed.</p><hr><h3 id="addtag" tabindex="-1">addTag() <a class="header-anchor" href="#addtag" aria-label="Permalink to “addTag()”">​</a></h3><blockquote><p><strong>addTag</strong>(<code>tag</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L1358" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:1358</a></p><p>Adds one of <code>/tag</code>&#39;s arbitrary string tags.</p><p>Java&#39;s <code>/tag</code> is exactly this and nothing more: a set of strings on the entity that <code>@e[tag=...]</code> tests and nothing else reads. The Bedrock client has no notion of it, so it never reaches the wire.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="tag" tabindex="-1">tag <a class="header-anchor" href="#tag" aria-label="Permalink to “tag”">​</a></h5><p><code>string</code></p><p>The tag.</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p><code>true</code> when the entity did not already carry it.</p><hr><h3 id="applyimpulse" tabindex="-1">applyImpulse() <a class="header-anchor" href="#applyimpulse" aria-label="Permalink to “applyImpulse()”">​</a></h3><blockquote><p><strong>applyImpulse</strong>(<code>_impulse</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L981" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:981</a></p><p>Applies a world-space impulse to an entity with a movement owner.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="impulse" tabindex="-1">_impulse <a class="header-anchor" href="#impulse" aria-label="Permalink to “_impulse”">​</a></h5><p><a href="./../../entities/#entityposition"><code>EntityPosition</code></a></p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="applyknockback" tabindex="-1">applyKnockback() <a class="header-anchor" href="#applyknockback" aria-label="Permalink to “applyKnockback()”">​</a></h3><blockquote><p><strong>applyKnockback</strong>(<code>_directionX</code>, <code>_directionZ</code>, <code>_strength</code>, <code>_damping?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L973" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:973</a></p><p>Shove this entity away from whatever hit it.</p><p>A no-op here, because the base entity has no velocity to shove. The two things that do override it, and they could hardly differ more: the body of a data-driven entity hands the impulse to the entity behind it and lets the runtime carry it, while a <code>Player</code> has to be <em>asked</em> - a player&#39;s position comes from their own client, so a server that moved them would be overruled on the next movement packet and read as rubber-banding.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="directionx" tabindex="-1">_directionX <a class="header-anchor" href="#directionx" aria-label="Permalink to “_directionX”">​</a></h5><p><code>number</code></p><p>Unit vector away from the blow, x.</p><h5 id="directionz" tabindex="-1">_directionZ <a class="header-anchor" href="#directionz" aria-label="Permalink to “_directionZ”">​</a></h5><p><code>number</code></p><p>Unit vector away from the blow, z.</p><h5 id="strength" tabindex="-1">_strength <a class="header-anchor" href="#strength" aria-label="Permalink to “_strength”">​</a></h5><p><code>number</code></p><p>How hard, with knockback resistance already taken off.</p><h5 id="damping" tabindex="-1">_damping? <a class="header-anchor" href="#damping" aria-label="Permalink to “_damping?”">​</a></h5><p><code>number</code> = <code>SINGLE_DAMPING</code></p><p>How much of the existing motion survives.</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="claimupdate" tabindex="-1">claimUpdate() <a class="header-anchor" href="#claimupdate" aria-label="Permalink to “claimUpdate()”">​</a></h3><blockquote><p><strong>claimUpdate</strong>(<code>tick</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L613" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:613</a></p><p>Claims this entity&#39;s one update of a server tick for the world asking.</p><p>The level ticks its worlds one after another, and a portal trip moves an entity from the world being ticked into one that is ticked later in the same pass. That world finds the arrival in its roster and would update it a second time. The first world claims the tick before updating; the second sees the claim and leaves the entity for the next tick.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="tick" tabindex="-1">tick <a class="header-anchor" href="#tick" aria-label="Permalink to “tick”">​</a></h5><p><code>number</code></p><p>The server&#39;s tick counter.</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p>True the first time a world asks for a given tick, false for every later ask.</p><hr><h3 id="clearstatuseffects" tabindex="-1">clearStatusEffects() <a class="header-anchor" href="#clearstatuseffects" aria-label="Permalink to “clearStatusEffects()”">​</a></h3><blockquote><p><strong>clearStatusEffects</strong>(<code>notify?</code>): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L778" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:778</a></p><p>Removes every active status effect.</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="notify-1" tabindex="-1">notify? <a class="header-anchor" href="#notify-1" aria-label="Permalink to “notify?”">​</a></h5><p><code>boolean</code> = <code>true</code></p><p>Whether to send a removal packet for each effect.</p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>The number of effects cleared.</p><hr><h3 id="damage" tabindex="-1">damage() <a class="header-anchor" href="#damage" aria-label="Permalink to “damage()”">​</a></h3><blockquote><p><strong>damage</strong>(<code>amount</code>, <code>source?</code>): <code>Promise</code>&lt;<code>boolean</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L828" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:828</a></p><p>Hurt the entity.</p><p>The whole pipeline, in vanilla&#39;s order: grace period, then the cancellable event, then armor and its enchantments, then resistance, then absorption, and only what is left of all that comes off the health.</p><p>Takes a bare <a href="./../#damagecause">DamageCause</a> as readily as a full DamageSource, which is what let the attacker be threaded through without touching any of the call sites - falling, drowning and starving never had one and still do not need one.</p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="amount" tabindex="-1">amount <a class="header-anchor" href="#amount" aria-label="Permalink to “amount”">​</a></h5><p><code>number</code></p><p>Half-hearts of damage, before any reduction. Ignored if not positive.</p><h5 id="source" tabindex="-1">source? <a class="header-anchor" href="#source" aria-label="Permalink to “source?”">​</a></h5><p><a href="./../#damagecause"><code>DamageCause</code></a> | <code>DamageSource</code> = <code>DamageCause.Generic</code></p><p>What did it, and who.</p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>boolean</code>&gt;</p><p><code>true</code> if the blow landed.</p><h4 id="example-2" tabindex="-1">Example <a class="header-anchor" href="#example-2" aria-label="Permalink to “Example”">​</a></h4><div class="language-typescript" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes jsprismarine jsprismarine" style="--shiki-light:#e5e7d7;--shiki-dark:#e5e7d7;--shiki-light-bg:#0b1713;--shiki-dark-bg:#0b1713;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">await</span><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;"> player.damage</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">(</span><span style="--shiki-light:#FF6B3D;--shiki-dark:#FF6B3D;">2</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">, DamageCause.Drowning);</span></span>\n<span class="line"><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">await</span><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;"> zombie.damage</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">(</span><span style="--shiki-light:#FF6B3D;--shiki-dark:#FF6B3D;">7</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">, </span><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;">DamageSource.entity</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">(player));</span></span></code></pre></div><hr><h3 id="despawnfrom" tabindex="-1">despawnFrom() <a class="header-anchor" href="#despawnfrom" aria-label="Permalink to “despawnFrom()”">​</a></h3><blockquote><p><strong>despawnFrom</strong>(<code>session</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L1234" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:1234</a></p><p>Takes this entity off one client.</p><h4 id="parameters-8" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-8" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="session" tabindex="-1">session <a class="header-anchor" href="#session" aria-label="Permalink to “session”">​</a></h5><p><a href="./PlayerSession.html"><code>PlayerSession</code></a></p><p>The client to remove it from.</p><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><p>A promise that resolves once the client has been told.</p><hr><h3 id="getarmordefensepoints" tabindex="-1">getArmorDefensePoints() <a class="header-anchor" href="#getarmordefensepoints" aria-label="Permalink to “getArmorDefensePoints()”">​</a></h3><blockquote><p><strong>getArmorDefensePoints</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L984" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:984</a></p><p>Armor points worn by this actor.</p><h4 id="returns-10" tabindex="-1">Returns <a class="header-anchor" href="#returns-10" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getarmortoughness" tabindex="-1">getArmorToughness() <a class="header-anchor" href="#getarmortoughness" aria-label="Permalink to “getArmorToughness()”">​</a></h3><blockquote><p><strong>getArmorToughness</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L996" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:996</a></p><p>Armor toughness worn, which softens what a hard blow does to that armor.</p><h4 id="returns-11" tabindex="-1">Returns <a class="header-anchor" href="#returns-11" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getbox" tabindex="-1">getBox() <a class="header-anchor" href="#getbox" aria-label="Permalink to “getBox()”">​</a></h3><blockquote><p><strong>getBox</strong>(): <a href="./../#entitybox"><code>EntityBox</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L311" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:311</a></p><p>How big this entity is, in blocks.</p><p>Read from the <code>minecraft:collision_box</code> of its type in the running content build rather than from a table in this repository, so the one number is whatever the pack stack says.</p><h4 id="returns-12" tabindex="-1">Returns <a class="header-anchor" href="#returns-12" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../#entitybox"><code>EntityBox</code></a></p><p>The box, centered on the position and extending up from the feet.</p><hr><h3 id="getdefaultportalcooldown" tabindex="-1">getDefaultPortalCooldown() <a class="header-anchor" href="#getdefaultportalcooldown" aria-label="Permalink to “getDefaultPortalCooldown()”">​</a></h3><blockquote><p><strong>getDefaultPortalCooldown</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L574" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:574</a></p><p>How long this entity refuses portals after a dimension change.</p><p>Vanilla&#39;s <code>getDimensionChangingDelay</code>: 300 ticks for an entity, and <code>Player</code> overrides it with 10.</p><h4 id="returns-13" tabindex="-1">Returns <a class="header-anchor" href="#returns-13" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>The cooldown in ticks, from <a href="./../#portal-cooldown-ticks">PORTAL_COOLDOWN_TICKS</a>.</p><hr><h3 id="getequipment" tabindex="-1">getEquipment() <a class="header-anchor" href="#getequipment" aria-label="Permalink to “getEquipment()”">​</a></h3><blockquote><p><strong>getEquipment</strong>(): <code>ViewableEquipment</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L1013" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:1013</a></p><p>What this entity is wearing and holding, by equipment slot.</p><p>Data-driven entities mirror equipment tables and interactions here. A <code>Human</code> overrides it from the armor container, the hand and the off hand.</p><h4 id="returns-14" tabindex="-1">Returns <a class="header-anchor" href="#returns-14" aria-label="Permalink to “Returns”">​</a></h4><p><code>ViewableEquipment</code></p><hr><h3 id="getfeety" tabindex="-1">getFeetY() <a class="header-anchor" href="#getfeety" aria-label="Permalink to “getFeetY()”">​</a></h3><blockquote><p><strong>getFeetY</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L669" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:669</a></p><p>The world height the bottom of this entity&#39;s body sits at.</p><p>The same as its position for everything the server moves itself, and deliberately a method rather than a read of <code>position.getY()</code> at each call site: a player&#39;s position is not its feet - see <code>Human</code> - so any comparison of one body against another has to go through this.</p><h4 id="returns-15" tabindex="-1">Returns <a class="header-anchor" href="#returns-15" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>Where the body starts, in world coordinates.</p><hr><h3 id="getformattedusername" tabindex="-1">getFormattedUsername() <a class="header-anchor" href="#getformattedusername" aria-label="Permalink to “getFormattedUsername()”">​</a></h3><blockquote><p><strong>getFormattedUsername</strong>(): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L1388" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:1388</a></p><p>Get the entity&#39;s formatted name.</p><h4 id="returns-16" tabindex="-1">Returns <a class="header-anchor" href="#returns-16" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><p>The entity&#39;s formatted name (including prefix &amp; suffix).</p><h4 id="example-3" tabindex="-1">Example <a class="header-anchor" href="#example-3" aria-label="Permalink to “Example”">​</a></h4><div class="language-typescript" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes jsprismarine jsprismarine" style="--shiki-light:#e5e7d7;--shiki-dark:#e5e7d7;--shiki-light-bg:#0b1713;--shiki-dark-bg:#0b1713;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">const</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;"> formattedName </span><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">=</span><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;"> entity.getFormattedUsername</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">();</span></span>\n<span class="line"><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;">console.log</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">(</span><span style="--shiki-light:#A9D9C6;--shiki-dark:#A9D9C6;">`Entity formatted name: ${</span><span style="--shiki-light:#A9D9C6;--shiki-dark:#A9D9C6;">formattedName</span><span style="--shiki-light:#A9D9C6;--shiki-dark:#A9D9C6;">}`</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">); </span><span style="--shiki-light:#7A9F90;--shiki-dark:#7A9F90;">// Entity formatted name: Sheep</span></span></code></pre></div><hr><h3 id="gethealth" tabindex="-1">getHealth() <a class="header-anchor" href="#gethealth" aria-label="Permalink to “getHealth()”">​</a></h3><blockquote><p><strong>getHealth</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L691" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:691</a></p><p>The entity&#39;s health, out of <a href="#getmaxhealth">Entity.getMaxHealth</a>.</p><p>Health is an attribute, not a field beside one: it is the same number the client draws its hearts from, so there is nowhere for the two to disagree.</p><h4 id="returns-17" tabindex="-1">Returns <a class="header-anchor" href="#returns-17" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>The health.</p><hr><h3 id="gethelditem" tabindex="-1">getHeldItem() <a class="header-anchor" href="#gethelditem" aria-label="Permalink to “getHeldItem()”">​</a></h3><blockquote><p><strong>getHeldItem</strong>(): <a href="./Item.html"><code>Item</code></a> | <code>null</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L331" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:331</a></p><p>What this entity is holding, for whoever has to draw it.</p><h4 id="returns-18" tabindex="-1">Returns <a class="header-anchor" href="#returns-18" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./Item.html"><code>Item</code></a> | <code>null</code></p><p>The item, or null for empty hands.</p><hr><h3 id="getlastdamagesource" tabindex="-1">getLastDamageSource() <a class="header-anchor" href="#getlastdamagesource" aria-label="Permalink to “getLastDamageSource()”">​</a></h3><blockquote><p><strong>getLastDamageSource</strong>(): <code>DamageSource</code> | <code>null</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L1123" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:1123</a></p><p>What last hurt this entity, if anything has.</p><p>How a mob knows who to fight back against, and how a death is reported as the work of somebody rather than of nothing in particular.</p><h4 id="returns-19" tabindex="-1">Returns <a class="header-anchor" href="#returns-19" aria-label="Permalink to “Returns”">​</a></h4><p><code>DamageSource</code> | <code>null</code></p><p>The last source, or null if it has never been hurt.</p><hr><h3 id="getmaxhealth" tabindex="-1">getMaxHealth() <a class="header-anchor" href="#getmaxhealth" aria-label="Permalink to “getMaxHealth()”">​</a></h3><blockquote><p><strong>getMaxHealth</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L699" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:699</a></p><p>The most health this entity can have.</p><h4 id="returns-20" tabindex="-1">Returns <a class="header-anchor" href="#returns-20" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>The maximum health.</p><hr><h3 id="getname" tabindex="-1">getName() <a class="header-anchor" href="#getname" aria-label="Permalink to “getName()”">​</a></h3><blockquote><p><strong>getName</strong>(): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L1333" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:1333</a></p><p>Get the entity&#39;s (potentially custom) name.</p><h4 id="returns-21" tabindex="-1">Returns <a class="header-anchor" href="#returns-21" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><p>The entity&#39;s name without formatting (usually prefix &amp; suffix).</p><h4 id="example-4" tabindex="-1">Example <a class="header-anchor" href="#example-4" aria-label="Permalink to “Example”">​</a></h4><div class="language-typescript" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes jsprismarine jsprismarine" style="--shiki-light:#e5e7d7;--shiki-dark:#e5e7d7;--shiki-light-bg:#0b1713;--shiki-dark-bg:#0b1713;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">const</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;"> name </span><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">=</span><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;"> entity.getName</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">();</span></span>\n<span class="line"><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;">console.log</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">(</span><span style="--shiki-light:#A9D9C6;--shiki-dark:#A9D9C6;">`Entity name: ${</span><span style="--shiki-light:#A9D9C6;--shiki-dark:#A9D9C6;">name</span><span style="--shiki-light:#A9D9C6;--shiki-dark:#A9D9C6;">}`</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">);</span></span></code></pre></div><hr><h3 id="getnearestentity" tabindex="-1">getNearestEntity() <a class="header-anchor" href="#getnearestentity" aria-label="Permalink to “getNearestEntity()”">​</a></h3><blockquote><p><strong>getNearestEntity</strong>(<code>entities?</code>): <code>Entity</code>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L484" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:484</a></p><p>Returns the nearest entity from the current entity.</p><h4 id="parameters-9" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-9" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entities" tabindex="-1">entities? <a class="header-anchor" href="#entities" aria-label="Permalink to “entities?”">​</a></h5><p><code>Entity</code>[] = <code>...</code></p><p>The entities to compare the distance between.</p><h4 id="returns-22" tabindex="-1">Returns <a class="header-anchor" href="#returns-22" aria-label="Permalink to “Returns”">​</a></h4><p><code>Entity</code>[]</p><p>The nearest entity.</p><h4 id="todo" tabindex="-1">Todo <a class="header-anchor" href="#todo" aria-label="Permalink to “Todo”">​</a></h4><p>Customizable radius</p><h4 id="example-5" tabindex="-1">Example <a class="header-anchor" href="#example-5" aria-label="Permalink to “Example”">​</a></h4><div class="language-typescript" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes jsprismarine jsprismarine" style="--shiki-light:#e5e7d7;--shiki-dark:#e5e7d7;--shiki-light-bg:#0b1713;--shiki-dark-bg:#0b1713;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">const</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;"> nearestEntity </span><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">=</span><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;"> entity.getNearestEntity</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">();</span></span>\n<span class="line"><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;">console.log</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">(</span><span style="--shiki-light:#A9D9C6;--shiki-dark:#A9D9C6;">&#39;Nearest entity:&#39;</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">, nearestEntity);</span></span></code></pre></div><hr><h3 id="getportalcooldown" tabindex="-1">getPortalCooldown() <a class="header-anchor" href="#getportalcooldown" aria-label="Permalink to “getPortalCooldown()”">​</a></h3><blockquote><p><strong>getPortalCooldown</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L581" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:581</a></p><p>Ticks left before this entity may enter a portal again.</p><h4 id="returns-23" tabindex="-1">Returns <a class="header-anchor" href="#returns-23" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getportaltransitionticks" tabindex="-1">getPortalTransitionTicks() <a class="header-anchor" href="#getportaltransitionticks" aria-label="Permalink to “getPortalTransitionTicks()”">​</a></h3><blockquote><p><strong>getPortalTransitionTicks</strong>(<code>_rule?</code>): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L563" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:563</a></p><p>Ticks this entity has to stand in a portal before it goes through.</p><p>Zero for everything that is not a player, as in vanilla: an item or a mob travels on the first contact tick. <code>Player</code> answers from its game mode and the portal&#39;s own delays.</p><h4 id="parameters-10" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-10" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="rule" tabindex="-1">_rule? <a class="header-anchor" href="#rule" aria-label="Permalink to “_rule?”">​</a></h5><p><code>PortalRule</code></p><p>The rule of the portal the entity stands in, when known. A nether portal holds a player for 80 ticks in survival and an end portal for none.</p><h4 id="returns-24" tabindex="-1">Returns <a class="header-anchor" href="#returns-24" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>The delay in ticks, from <a href="./../#portal-transition-ticks">PORTAL_TRANSITION_TICKS</a>.</p><hr><h3 id="getposition" tabindex="-1">getPosition() <a class="header-anchor" href="#getposition" aria-label="Permalink to “getPosition()”">​</a></h3><blockquote><p><strong>getPosition</strong>(): <a href="./Position.html"><code>Position</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L453" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:453</a></p><p>Get the entity&#39;s position.</p><h4 id="returns-25" tabindex="-1">Returns <a class="header-anchor" href="#returns-25" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./Position.html"><code>Position</code></a></p><p>Where the entity is, and in which world.</p><h4 id="remarks-1" tabindex="-1">Remarks <a class="header-anchor" href="#remarks-1" aria-label="Permalink to “Remarks”">​</a></h4><p>The stored position, not a copy. It is safe to hand out because a position derives new instances instead of mutating itself, so a caller cannot move the entity through it. Previously this built a fresh <code>Vector3</code> on every call - one allocation per packet - and that vector had dropped the world, so <code>getWorld()</code> on it was unavailable.</p><h4 id="example-6" tabindex="-1">Example <a class="header-anchor" href="#example-6" aria-label="Permalink to “Example”">​</a></h4><div class="language-typescript" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes jsprismarine jsprismarine" style="--shiki-light:#e5e7d7;--shiki-dark:#e5e7d7;--shiki-light-bg:#0b1713;--shiki-dark-bg:#0b1713;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">const</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;"> position </span><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">=</span><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;"> entity.getPosition</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">();</span></span></code></pre></div><hr><h3 id="getruntimeid" tabindex="-1">getRuntimeId() <a class="header-anchor" href="#getruntimeid" aria-label="Permalink to “getRuntimeId()”">​</a></h3><blockquote><p><strong>getRuntimeId</strong>(): <code>bigint</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L437" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:437</a></p><p>Get the entity&#39;s runtime id.</p><h4 id="returns-26" tabindex="-1">Returns <a class="header-anchor" href="#returns-26" aria-label="Permalink to “Returns”">​</a></h4><p><code>bigint</code></p><p>The entity&#39;s runtime id.</p><h4 id="example-7" tabindex="-1">Example <a class="header-anchor" href="#example-7" aria-label="Permalink to “Example”">​</a></h4><div class="language-typescript" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes jsprismarine jsprismarine" style="--shiki-light:#e5e7d7;--shiki-dark:#e5e7d7;--shiki-light-bg:#0b1713;--shiki-dark-bg:#0b1713;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">const</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;"> entityId </span><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">=</span><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;"> entity.getRuntimeId</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">();</span></span>\n<span class="line"><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;">console.log</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">(entityId); </span><span style="--shiki-light:#7A9F90;--shiki-dark:#7A9F90;">// Ex. Output: 1n</span></span></code></pre></div><hr><h3 id="getserver" tabindex="-1">getServer() <a class="header-anchor" href="#getserver" aria-label="Permalink to “getServer()”">​</a></h3><blockquote><p><strong>getServer</strong>(): <a href="./Server.html"><code>Server</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L1167" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:1167</a></p><p>Get the server instance.</p><h4 id="returns-27" tabindex="-1">Returns <a class="header-anchor" href="#returns-27" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./Server.html"><code>Server</code></a></p><p>The server instance.</p><h4 id="example-8" tabindex="-1">Example <a class="header-anchor" href="#example-8" aria-label="Permalink to “Example”">​</a></h4><div class="language-typescript" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes jsprismarine jsprismarine" style="--shiki-light:#e5e7d7;--shiki-dark:#e5e7d7;--shiki-light-bg:#0b1713;--shiki-dark-bg:#0b1713;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">const</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;"> server </span><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">=</span><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;"> entity.getServer</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">();</span></span>\n<span class="line"><span style="--shiki-light:#7A9F90;--shiki-dark:#7A9F90;">// Do things with the server.</span></span></code></pre></div><hr><h3 id="getstatuseffect" tabindex="-1">getStatusEffect() <a class="header-anchor" href="#getstatuseffect" aria-label="Permalink to “getStatusEffect()”">​</a></h3><blockquote><p><strong>getStatusEffect</strong>(<code>identifier</code>): <a href="./../#statuseffect"><code>StatusEffect</code></a> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L724" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:724</a></p><p>Reads one active effect by its namespaced id or bare Bedrock effect name.</p><h4 id="parameters-11" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-11" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="identifier" tabindex="-1">identifier <a class="header-anchor" href="#identifier" aria-label="Permalink to “identifier”">​</a></h5><p><code>string</code></p><p>The effect name.</p><h4 id="returns-28" tabindex="-1">Returns <a class="header-anchor" href="#returns-28" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../#statuseffect"><code>StatusEffect</code></a> | <code>undefined</code></p><p>The active effect, or undefined when it is absent.</p><hr><h3 id="getstatuseffects" tabindex="-1">getStatusEffects() <a class="header-anchor" href="#getstatuseffects" aria-label="Permalink to “getStatusEffects()”">​</a></h3><blockquote><p><strong>getStatusEffects</strong>(): readonly <a href="./../#statuseffect"><code>StatusEffect</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L715" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:715</a></p><p>The active effects this entity currently carries.</p><h4 id="returns-29" tabindex="-1">Returns <a class="header-anchor" href="#returns-29" aria-label="Permalink to “Returns”">​</a></h4><p>readonly <a href="./../#statuseffect"><code>StatusEffect</code></a>[]</p><p>A snapshot of the active effect instances.</p><hr><h3 id="getsyncedproperties" tabindex="-1">getSyncedProperties() <a class="header-anchor" href="#getsyncedproperties" aria-label="Permalink to “getSyncedProperties()”">​</a></h3><blockquote><p><strong>getSyncedProperties</strong>(): <code>SyncedProperties</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L1024" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:1024</a></p><p>The properties this actor sends alongside its metadata.</p><p>Most entities do not have data-driven properties. Data-driven entity bodies override this with their current client-synced values.</p><h4 id="returns-30" tabindex="-1">Returns <a class="header-anchor" href="#returns-30" aria-label="Permalink to “Returns”">​</a></h4><p><code>SyncedProperties</code></p><p>The actor&#39;s current property snapshot.</p><hr><h3 id="gettags" tabindex="-1">getTags() <a class="header-anchor" href="#gettags" aria-label="Permalink to “getTags()”">​</a></h3><blockquote><p><strong>getTags</strong>(): readonly <code>string</code>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L1375" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:1375</a></p><p>The <code>/tag</code> tags this entity carries, in the order they were added.</p><h4 id="returns-31" tabindex="-1">Returns <a class="header-anchor" href="#returns-31" aria-label="Permalink to “Returns”">​</a></h4><p>readonly <code>string</code>[]</p><hr><h3 id="gettrackinginterval" tabindex="-1">getTrackingInterval() <a class="header-anchor" href="#gettrackinginterval" aria-label="Permalink to “getTrackingInterval()”">​</a></h3><blockquote><p><strong>getTrackingInterval</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L1209" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:1209</a></p><p>Ticks between visibility passes for this entity.</p><p>Only governs entities approaching a <em>standing</em> player: a player who moves crosses a chunk boundary and forces a pass regardless. Things that never move on their own can afford a long interval.</p><h4 id="returns-32" tabindex="-1">Returns <a class="header-anchor" href="#returns-32" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>The interval in ticks.</p><hr><h3 id="gettrackingrange" tabindex="-1">getTrackingRange() <a class="header-anchor" href="#gettrackingrange" aria-label="Permalink to “getTrackingRange()”">​</a></h3><blockquote><p><strong>getTrackingRange</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L1197" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:1197</a></p><p>How far clients follow this entity, in chunks.</p><p>Per type rather than one number for everything, which is how vanilla does it: a client is told about players as far as it can see, ordinary mobs a little less far, and dropped items less far still. Items are the reason the distinction matters - they are by far the most numerous entity and the least interesting at a distance, so a single radius means a mob farm streams thousands of them to everyone in range.</p><p>Always narrowed by the recipient&#39;s own view distance, so this can never widen an audience past the terrain that client actually holds.</p><h4 id="returns-33" tabindex="-1">Returns <a class="header-anchor" href="#returns-33" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>The tracking radius in chunks.</p><hr><h3 id="gettype" tabindex="-1">getType() <a class="header-anchor" href="#gettype" aria-label="Permalink to “getType()”">​</a></h3><blockquote><p><strong>getType</strong>(): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L413" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:413</a></p><h4 id="returns-34" tabindex="-1">Returns <a class="header-anchor" href="#returns-34" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><hr><h3 id="getvelocity" tabindex="-1">getVelocity() <a class="header-anchor" href="#getvelocity" aria-label="Permalink to “getVelocity()”">​</a></h3><blockquote><p><strong>getVelocity</strong>(): <a href="./../../math/classes/Vector3.html"><code>Vector3</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L461" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:461</a></p><p>The actor&#39;s current velocity in blocks per tick, or zero when it has none.</p><h4 id="returns-35" tabindex="-1">Returns <a class="header-anchor" href="#returns-35" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../../math/classes/Vector3.html"><code>Vector3</code></a></p><p>The actor&#39;s current velocity.</p><hr><h3 id="getworld" tabindex="-1">getWorld() <a class="header-anchor" href="#getworld" aria-label="Permalink to “getWorld()”">​</a></h3><blockquote><p><strong>getWorld</strong>(): <a href="./World.html"><code>World</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L469" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:469</a></p><p>Gets the world the entity is currently in.</p><h4 id="returns-36" tabindex="-1">Returns <a class="header-anchor" href="#returns-36" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./World.html"><code>World</code></a></p><p>The world.</p><hr><h3 id="hasstatuseffect" tabindex="-1">hasStatusEffect() <a class="header-anchor" href="#hasstatuseffect" aria-label="Permalink to “hasStatusEffect()”">​</a></h3><blockquote><p><strong>hasStatusEffect</strong>(<code>identifier</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L733" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:733</a></p><p>Whether one status effect is active.</p><h4 id="parameters-12" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-12" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="identifier-1" tabindex="-1">identifier <a class="header-anchor" href="#identifier-1" aria-label="Permalink to “identifier”">​</a></h5><p><code>string</code></p><p>The effect name.</p><h4 id="returns-37" tabindex="-1">Returns <a class="header-anchor" href="#returns-37" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p>Whether it is active.</p><hr><h3 id="heal" tabindex="-1">heal() <a class="header-anchor" href="#heal" aria-label="Permalink to “heal()”">​</a></h3><blockquote><p><strong>heal</strong>(<code>amount</code>): <code>Promise</code>&lt;<code>boolean</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L1137" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:1137</a></p><p>Heal the entity, up to its maximum.</p><h4 id="parameters-13" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-13" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="amount-1" tabindex="-1">amount <a class="header-anchor" href="#amount-1" aria-label="Permalink to “amount”">​</a></h5><p><code>number</code></p><p>Half-hearts to restore. Ignored if not positive.</p><h4 id="returns-38" tabindex="-1">Returns <a class="header-anchor" href="#returns-38" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>boolean</code>&gt;</p><p><code>true</code> if any health was actually restored.</p><hr><h3 id="isalive" tabindex="-1">isAlive() <a class="header-anchor" href="#isalive" aria-label="Permalink to “isAlive()”">​</a></h3><blockquote><p><strong>isAlive</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L707" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:707</a></p><p>Whether the entity has any health left.</p><h4 id="returns-39" tabindex="-1">Returns <a class="header-anchor" href="#returns-39" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p><code>true</code> while it is alive.</p><hr><h3 id="isinvulnerabletohits" tabindex="-1">isInvulnerableToHits() <a class="header-anchor" href="#isinvulnerabletohits" aria-label="Permalink to “isInvulnerableToHits()”">​</a></h3><blockquote><p><strong>isInvulnerableToHits</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L1128" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:1128</a></p><p>Whether the entity is still inside the grace period after a hit.</p><h4 id="returns-40" tabindex="-1">Returns <a class="header-anchor" href="#returns-40" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="isonground" tabindex="-1">isOnGround() <a class="header-anchor" href="#isonground" aria-label="Permalink to “isOnGround()”">​</a></h3><blockquote><p><strong>isOnGround</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L371" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:371</a></p><p>Whether this entity is standing on something.</p><p>What <code>MoveActorAbsolutePacket</code>&#39;s on-ground flag carries, and what the <code>is_on_ground</code> predicate reads. False for anything nothing keeps the state for, which is every entity but a data-driven mob and a player: a projectile in flight and a dropped item are both drawn by the client from its own guess, as they were before the flag was sent at all.</p><h4 id="returns-41" tabindex="-1">Returns <a class="header-anchor" href="#returns-41" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p>Whether it is grounded.</p><hr><h3 id="isonportalcooldown" tabindex="-1">isOnPortalCooldown() <a class="header-anchor" href="#isonportalcooldown" aria-label="Permalink to “isOnPortalCooldown()”">​</a></h3><blockquote><p><strong>isOnPortalCooldown</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L598" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:598</a></p><p>Whether this entity is still refusing portals after a recent dimension change.</p><h4 id="returns-42" tabindex="-1">Returns <a class="header-anchor" href="#returns-42" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="occupiesspace" tabindex="-1">occupiesSpace() <a class="header-anchor" href="#occupiesspace" aria-label="Permalink to “occupiesSpace()”">​</a></h3><blockquote><p><strong>occupiesSpace</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L657" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:657</a></p><p>Whether other entities are kept out of the space this one is in.</p><p>False for nearly everything, and deliberately: an arrow in flight, an item on the floor and a painting on the wall are all things you walk through, and shoving a mob aside for them would be both wrong and expensive. <code>Human</code> overrides it, which is what shoves a mob out of a player&#39;s way.</p><h4 id="returns-43" tabindex="-1">Returns <a class="header-anchor" href="#returns-43" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p>Whether this entity displaces others.</p><hr><h3 id="portalcontact" tabindex="-1">portalContact() <a class="header-anchor" href="#portalcontact" aria-label="Permalink to “portalContact()”">​</a></h3><blockquote><p><strong>portalContact</strong>(): <a href="./PortalContact.html"><code>PortalContact</code></a> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L622" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:622</a></p><p>The portal this entity is currently in contact with, if any.</p><h4 id="returns-44" tabindex="-1">Returns <a class="header-anchor" href="#returns-44" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./PortalContact.html"><code>PortalContact</code></a> | <code>undefined</code></p><hr><h3 id="removestatuseffect" tabindex="-1">removeStatusEffect() <a class="header-anchor" href="#removestatuseffect" aria-label="Permalink to “removeStatusEffect()”">​</a></h3><blockquote><p><strong>removeStatusEffect</strong>(<code>identifier</code>, <code>notify?</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L764" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:764</a></p><p>Removes one status effect.</p><h4 id="parameters-14" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-14" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="identifier-2" tabindex="-1">identifier <a class="header-anchor" href="#identifier-2" aria-label="Permalink to “identifier”">​</a></h5><p><code>string</code></p><p>The effect name.</p><h5 id="notify-2" tabindex="-1">notify? <a class="header-anchor" href="#notify-2" aria-label="Permalink to “notify?”">​</a></h5><p><code>boolean</code> = <code>true</code></p><p>Whether to send a removal packet.</p><h4 id="returns-45" tabindex="-1">Returns <a class="header-anchor" href="#returns-45" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p>Whether an active effect was removed.</p><hr><h3 id="removetag" tabindex="-1">removeTag() <a class="header-anchor" href="#removetag" aria-label="Permalink to “removeTag()”">​</a></h3><blockquote><p><strong>removeTag</strong>(<code>tag</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L1370" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:1370</a></p><p>Removes one of <code>/tag</code>&#39;s tags.</p><h4 id="parameters-15" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-15" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="tag-1" tabindex="-1">tag <a class="header-anchor" href="#tag-1" aria-label="Permalink to “tag”">​</a></h5><p><code>string</code></p><p>The tag.</p><h4 id="returns-46" tabindex="-1">Returns <a class="header-anchor" href="#returns-46" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p><code>true</code> when the entity carried it.</p><hr><h3 id="setequipment" tabindex="-1">setEquipment() <a class="header-anchor" href="#setequipment" aria-label="Permalink to “setEquipment()”">​</a></h3><blockquote><p><strong>setEquipment</strong>(<code>equipment</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L357" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:357</a></p><p>Replaces everything this entity is holding and wearing.</p><p>Stored rather than broadcast, for the reason <a href="#sethelditem">Entity.setHeldItem</a> is. The two places that put it on the wire are <code>PlayerSession.sendAddActor</code>, for a client being shown the entity, and <code>WorldChangeSink.entityEquipmentChanged</code>, for one already holding it.</p><h4 id="parameters-16" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-16" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="equipment" tabindex="-1">equipment <a class="header-anchor" href="#equipment" aria-label="Permalink to “equipment”">​</a></h5><p><code>ViewableEquipment</code></p><p>The new set, replacing the old one whole.</p><h4 id="returns-47" tabindex="-1">Returns <a class="header-anchor" href="#returns-47" aria-label="Permalink to “Returns”">​</a></h4><p><code>this</code></p><p>The entity, so a caller can chain.</p><hr><h3 id="setgrounded" tabindex="-1">setGrounded() <a class="header-anchor" href="#setgrounded" aria-label="Permalink to “setGrounded()”">​</a></h3><blockquote><p><strong>setGrounded</strong>(<code>grounded</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L384" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:384</a></p><p>Records whether this entity is standing on something.</p><p>Named apart from <code>Player.setOnGround</code>, which is the client reporting it for its own entity and which also pays out the fall damage the landing earned. This one is the server&#39;s own answer for an entity it is moving itself.</p><h4 id="parameters-17" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-17" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="grounded" tabindex="-1">grounded <a class="header-anchor" href="#grounded" aria-label="Permalink to “grounded”">​</a></h5><p><code>boolean</code></p><p>Whether it is standing on something.</p><h4 id="returns-48" tabindex="-1">Returns <a class="header-anchor" href="#returns-48" aria-label="Permalink to “Returns”">​</a></h4><p><code>this</code></p><p>The entity, so a caller can chain.</p><hr><h3 id="sethealth" tabindex="-1">setHealth() <a class="header-anchor" href="#sethealth" aria-label="Permalink to “setHealth()”">​</a></h3><blockquote><p><strong>setHealth</strong>(<code>health</code>, <code>source?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L792" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:792</a></p><p>Set the entity&#39;s health, killing it if that leaves it at zero.</p><h4 id="parameters-18" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-18" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="health" tabindex="-1">health <a class="header-anchor" href="#health" aria-label="Permalink to “health”">​</a></h5><p><code>number</code></p><p>The wanted health; clamped to the attribute&#39;s bounds.</p><h5 id="source-1" tabindex="-1">source? <a class="header-anchor" href="#source-1" aria-label="Permalink to “source?”">​</a></h5><p><a href="./../#damagecause"><code>DamageCause</code></a> | <code>DamageSource</code> = <code>DamageCause.Generic</code></p><p>What to report as the cause if this kills it.</p><h4 id="returns-49" tabindex="-1">Returns <a class="header-anchor" href="#returns-49" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sethelditem" tabindex="-1">setHeldItem() <a class="header-anchor" href="#sethelditem" aria-label="Permalink to “setHeldItem()”">​</a></h3><blockquote><p><strong>setHeldItem</strong>(<code>item</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L344" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:344</a></p><p>Puts something in this entity&#39;s hand.</p><p>Stored rather than broadcast, because an entity is often given its item before it is in a world and there is nobody to tell. Everyone who can see it is told when it is spawned to them - see <code>PlayerSession.sendAddActor</code>.</p><h4 id="parameters-19" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-19" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="item" tabindex="-1">item <a class="header-anchor" href="#item" aria-label="Permalink to “item”">​</a></h5><p><a href="./Item.html"><code>Item</code></a> | <code>null</code></p><p>What to hold.</p><h4 id="returns-50" tabindex="-1">Returns <a class="header-anchor" href="#returns-50" aria-label="Permalink to “Returns”">​</a></h4><p><code>this</code></p><p>The entity, so a caller can chain.</p><hr><h3 id="setname" tabindex="-1">setName() <a class="header-anchor" href="#setname" aria-label="Permalink to “setName()”">​</a></h3><blockquote><p><strong>setName</strong>(<code>name</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L1345" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:1345</a></p><p>Set the entity&#39;s name.</p><h4 id="parameters-20" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-20" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to “name”">​</a></h5><p><code>string</code></p><p>The name.</p><h4 id="returns-51" tabindex="-1">Returns <a class="header-anchor" href="#returns-51" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><h4 id="example-9" tabindex="-1">Example <a class="header-anchor" href="#example-9" aria-label="Permalink to “Example”">​</a></h4><div class="language-typescript" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes jsprismarine jsprismarine" style="--shiki-light:#e5e7d7;--shiki-dark:#e5e7d7;--shiki-light-bg:#0b1713;--shiki-dark-bg:#0b1713;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;">entity.setName</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">(</span><span style="--shiki-light:#A9D9C6;--shiki-dark:#A9D9C6;">&#39;Mr. Sheep&#39;</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">);</span></span></code></pre></div><hr><h3 id="setportalcooldown" tabindex="-1">setPortalCooldown() <a class="header-anchor" href="#setportalcooldown" aria-label="Permalink to “setPortalCooldown()”">​</a></h3><blockquote><p><strong>setPortalCooldown</strong>(<code>ticks?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L591" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:591</a></p><p>Starts the portal cooldown.</p><p>Called on departure, and by the serializer when restoring a saved actor.</p><h4 id="parameters-21" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-21" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="ticks" tabindex="-1">ticks? <a class="header-anchor" href="#ticks" aria-label="Permalink to “ticks?”">​</a></h5><p><code>number</code> = <code>...</code></p><p>The cooldown in ticks. Defaults to <a href="#getdefaultportalcooldown">Entity.getDefaultPortalCooldown</a>.</p><h4 id="returns-52" tabindex="-1">Returns <a class="header-anchor" href="#returns-52" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="setposition" tabindex="-1">setPosition() <a class="header-anchor" href="#setposition" aria-label="Permalink to “setPosition()”">​</a></h3><blockquote><p><strong>setPosition</strong>(<code>options</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L1303" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:1303</a></p><p>Set the entity&#39;s position and notify the clients.</p><h4 id="parameters-22" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-22" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="options-1" tabindex="-1">options <a class="header-anchor" href="#options-1" aria-label="Permalink to “options”">​</a></h5><p><a href="./../#entitypositionoptions"><code>EntityPositionOptions</code></a></p><p>The position options.</p><h4 id="returns-53" tabindex="-1">Returns <a class="header-anchor" href="#returns-53" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><p>A promise that resolves when the position is set.</p><h4 id="throws" tabindex="-1">Throws <a class="header-anchor" href="#throws" aria-label="Permalink to “Throws”">​</a></h4><p>When a coordinate is NaN or infinite. The entity stays where it was, since a position like that cannot be encoded for the client anyway.</p><h4 id="remarks-2" tabindex="-1">Remarks <a class="header-anchor" href="#remarks-2" aria-label="Permalink to “Remarks”">​</a></h4><p>A bare <code>Vector3</code> is taken to mean the same world the entity is already in; moving between worlds goes through the world change on <code>Player</code>, not through here.</p><hr><h3 id="setx" tabindex="-1">setX() <a class="header-anchor" href="#setx" aria-label="Permalink to “setX()”">​</a></h3><blockquote><p><strong>setX</strong>(<code>x</code>, <code>suppress?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L1252" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:1252</a></p><p>Set the <code>x</code> position.</p><h4 id="parameters-23" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-23" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x" tabindex="-1">x <a class="header-anchor" href="#x" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><p>The <code>x</code> coordinate.</p><h5 id="suppress" tabindex="-1">suppress? <a class="header-anchor" href="#suppress" aria-label="Permalink to “suppress?”">​</a></h5><p><code>boolean</code> = <code>false</code></p><p>If true, the client won&#39;t be notified about the position change.</p><h4 id="returns-54" tabindex="-1">Returns <a class="header-anchor" href="#returns-54" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><p>A promise that resolves when the x position is set.</p><h4 id="example-10" tabindex="-1">Example <a class="header-anchor" href="#example-10" aria-label="Permalink to “Example”">​</a></h4><div class="language-typescript" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes jsprismarine jsprismarine" style="--shiki-light:#e5e7d7;--shiki-dark:#e5e7d7;--shiki-light-bg:#0b1713;--shiki-dark-bg:#0b1713;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">await</span><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;"> entity.setX</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">(</span><span style="--shiki-light:#FF6B3D;--shiki-dark:#FF6B3D;">10</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">);</span></span></code></pre></div><h4 id="remarks-3" tabindex="-1">Remarks <a class="header-anchor" href="#remarks-3" aria-label="Permalink to “Remarks”">​</a></h4><p>This method will also send the position update to the client if <code>suppress</code> is <code>false</code>. The test read the flag the wrong way round, so it notified only when asked not to - which, since nothing passed the flag, meant an entity could be moved anywhere without a single client hearing about it.</p><hr><h3 id="sety" tabindex="-1">setY() <a class="header-anchor" href="#sety" aria-label="Permalink to “setY()”">​</a></h3><blockquote><p><strong>setY</strong>(<code>y</code>, <code>suppress?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L1268" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:1268</a></p><p>Set the <code>y</code> position.</p><h4 id="parameters-24" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-24" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="y" tabindex="-1">y <a class="header-anchor" href="#y" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><p>The <code>y</code> coordinate.</p><h5 id="suppress-1" tabindex="-1">suppress? <a class="header-anchor" href="#suppress-1" aria-label="Permalink to “suppress?”">​</a></h5><p><code>boolean</code> = <code>false</code></p><p>If true, the client won&#39;t be notified about the position change.</p><h4 id="returns-55" tabindex="-1">Returns <a class="header-anchor" href="#returns-55" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><p>A promise that resolves when the y position is set.</p><h4 id="example-11" tabindex="-1">Example <a class="header-anchor" href="#example-11" aria-label="Permalink to “Example”">​</a></h4><div class="language-typescript" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes jsprismarine jsprismarine" style="--shiki-light:#e5e7d7;--shiki-dark:#e5e7d7;--shiki-light-bg:#0b1713;--shiki-dark-bg:#0b1713;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">await</span><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;"> entity.setY</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">(</span><span style="--shiki-light:#FF6B3D;--shiki-dark:#FF6B3D;">10</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">);</span></span></code></pre></div><h4 id="remarks-4" tabindex="-1">Remarks <a class="header-anchor" href="#remarks-4" aria-label="Permalink to “Remarks”">​</a></h4><p>This method will also send the position update to the client if <code>suppress</code> is <code>false</code>.</p><hr><h3 id="setz" tabindex="-1">setZ() <a class="header-anchor" href="#setz" aria-label="Permalink to “setZ()”">​</a></h3><blockquote><p><strong>setZ</strong>(<code>z</code>, <code>suppress?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L1284" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:1284</a></p><p>Set the <code>z</code> position.</p><h4 id="parameters-25" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-25" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="z" tabindex="-1">z <a class="header-anchor" href="#z" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><p>The <code>z</code> coordinate.</p><h5 id="suppress-2" tabindex="-1">suppress? <a class="header-anchor" href="#suppress-2" aria-label="Permalink to “suppress?”">​</a></h5><p><code>boolean</code> = <code>false</code></p><p>If true, the client won&#39;t be notified about the position change.</p><h4 id="returns-56" tabindex="-1">Returns <a class="header-anchor" href="#returns-56" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><p>A promise that resolves when the z position is set.</p><h4 id="example-12" tabindex="-1">Example <a class="header-anchor" href="#example-12" aria-label="Permalink to “Example”">​</a></h4><div class="language-typescript" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes jsprismarine jsprismarine" style="--shiki-light:#e5e7d7;--shiki-dark:#e5e7d7;--shiki-light-bg:#0b1713;--shiki-dark-bg:#0b1713;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#5CA48A;--shiki-dark:#5CA48A;">await</span><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;"> entity.setZ</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">(</span><span style="--shiki-light:#FF6B3D;--shiki-dark:#FF6B3D;">10</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">);</span></span></code></pre></div><h4 id="remarks-5" tabindex="-1">Remarks <a class="header-anchor" href="#remarks-5" aria-label="Permalink to “Remarks”">​</a></h4><p>This method will also send the position update to the client if <code>suppress</code> is <code>false</code>.</p><hr><h3 id="shouldpersist" tabindex="-1">shouldPersist() <a class="header-anchor" href="#shouldpersist" aria-label="Permalink to “shouldPersist()”">​</a></h3><blockquote><p><strong>shouldPersist</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L680" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:680</a></p><p>Whether the world should include this entity in saved actor records.</p><p>Most entities survive a world save. A data-driven entity can opt out with Bedrock&#39;s <code>minecraft:transient</code> component.</p><h4 id="returns-57" tabindex="-1">Returns <a class="header-anchor" href="#returns-57" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p>Whether this entity should be persisted.</p><hr><h3 id="spawnto" tabindex="-1">spawnTo() <a class="header-anchor" href="#spawnto" aria-label="Permalink to “spawnTo()”">​</a></h3><blockquote><p><strong>spawnTo</strong>(<code>session</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L1225" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:1225</a></p><p>Shows this entity to one client.</p><p>The entity names the call that represents it and nothing more: it builds no packet and does not go looking for an audience. Deciding who is shown what belongs to the world, and what that looks like on the wire belongs to the session.</p><p>A subclass overrides this when it appears as something other than a generic actor - which is why this is a method and not a type test inside the session.</p><h4 id="parameters-26" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-26" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="session-1" tabindex="-1">session <a class="header-anchor" href="#session-1" aria-label="Permalink to “session”">​</a></h5><p><a href="./PlayerSession.html"><code>PlayerSession</code></a></p><p>The client to show it to.</p><h4 id="returns-58" tabindex="-1">Returns <a class="header-anchor" href="#returns-58" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><p>A promise that resolves once the client has been told.</p><hr><h3 id="tostring" tabindex="-1">toString() <a class="header-anchor" href="#tostring" aria-label="Permalink to “toString()”">​</a></h3><blockquote><p><strong>toString</strong>(): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L424" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:424</a></p><p>Convert to a string representation.</p><h4 id="returns-59" tabindex="-1">Returns <a class="header-anchor" href="#returns-59" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><p>The string.</p><div class="language-typescript" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes jsprismarine jsprismarine" style="--shiki-light:#e5e7d7;--shiki-dark:#e5e7d7;--shiki-light-bg:#0b1713;--shiki-dark-bg:#0b1713;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;">console.log</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">(</span><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;">entity.toString</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">());</span></span></code></pre></div><hr><h3 id="touchportal" tabindex="-1">touchPortal() <a class="header-anchor" href="#touchportal" aria-label="Permalink to “touchPortal()”">​</a></h3><blockquote><p><strong>touchPortal</strong>(<code>at</code>, <code>portal?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L638" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:638</a></p><p>Records that this entity overlaps a portal block on the current tick.</p><p>The world calls this once per tick for each entity whose box overlaps a portal. The first call opens the contact; later calls refresh it. A touch while on cooldown opens nothing and winds the cooldown back to its full length instead, as Java&#39;s <code>Entity.setAsInsidePortal</code> does, so an entity that has just arrived only travels again after it has left the portal for the whole cooldown and stepped back in.</p><h4 id="parameters-27" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-27" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="at" tabindex="-1">at <a class="header-anchor" href="#at" aria-label="Permalink to “at”">​</a></h5><p><a href="./../../math/classes/Vector3.html"><code>Vector3</code></a></p><p>Where the entity stands, kept as the contact&#39;s entry position.</p><h5 id="portal" tabindex="-1">portal? <a class="header-anchor" href="#portal" aria-label="Permalink to “portal?”">​</a></h5><p><code>PortalBlockRef</code></p><p>The portal block overlapped, which the trip is resolved from. Without one the contact counts but never travels.</p><h4 id="returns-60" tabindex="-1">Returns <a class="header-anchor" href="#returns-60" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="update" tabindex="-1">update() <a class="header-anchor" href="#update" aria-label="Permalink to “update()”">​</a></h3><blockquote><p><strong>update</strong>(<code>_tick</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/26444a9f54cb521476805553db9daea2ceea7270/packages/prismarine/src/entity/Entity.ts#L514" target="_blank" rel="noreferrer">prismarine/src/entity/Entity.ts:514</a></p><p>Fired every tick by the world.</p><p>Subclasses that override this must call up, or the grace period after a hit never runs down and the entity becomes permanently unhurtable after the first blow.</p><h4 id="parameters-28" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-28" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="tick-1" tabindex="-1">_tick <a class="header-anchor" href="#tick-1" aria-label="Permalink to “_tick”">​</a></h5><p><code>number</code></p><p>The current world-tick.</p><h4 id="returns-61" tabindex="-1">Returns <a class="header-anchor" href="#returns-61" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><p>A promise that resolves when the update is complete.</p><h4 id="example-13" tabindex="-1">Example <a class="header-anchor" href="#example-13" aria-label="Permalink to “Example”">​</a></h4><div class="language-typescript" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes jsprismarine jsprismarine" style="--shiki-light:#e5e7d7;--shiki-dark:#e5e7d7;--shiki-light-bg:#0b1713;--shiki-dark-bg:#0b1713;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#EFE9DA;--shiki-dark:#EFE9DA;">entity.update</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">(</span><span style="--shiki-light:#FF6B3D;--shiki-dark:#FF6B3D;">10</span><span style="--shiki-light:#E5E7D7;--shiki-dark:#E5E7D7;">);</span></span></code></pre></div>',759)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};